def english_report(report):
    # Replace longer strings first to preserve sentence context.
    for zh, en in sorted(TEXT_EN.items(), key=lambda item: len(item[0]), reverse=True):
        report = report.replace(zh, en)
    for zh, en in SHEETS_EN.items():
        report = report.replace(zh.replace("底稿", ""), en)
    report = report.replace("114 年 1 月至 12 月", "January–December 2025")
    report = report.replace("114 年 1 月", "January 2025").replace("114 年 12 月", "December 2025")
    report = report.replace("tCO₂e", "tCO₂e")
    return report
